# -*- coding: utf-8 -*-
"""دفعة 4 — ترقية 3 مقالات لمصادر حكومية رسمية (11 صحيفة جنائية / 12 نقل القيد / 15 منصة مصر الرقمية)
كل معلومة من مصادر رسمية موثقة في sources-log.md بتاريخ 1/10/2026،
وما لم يتوفر له مصدر رسمي (فئات رسوم صحيفة الحالة الجنائية) اتحذف وفق سقف الجودة.
Atomic patch: يفشل كله أو ينفع كله — بدون تعديل جزئي."""
import re, sys, shutil

PATH = "articles.html"
BAK = "articles.html.bak-batch4"

UPDATES = {
    "إزاي تستخرج صحيفة حالة جنائية؟":
        r"""<h3>📋 الخطوات (أونلاين)</h3><p>1. ادخل على <a href=\"https://digital.gov.eg\" target=\"_blank\">بوابة مصر الرقمية</a> واختار خدمة «إصدار صحيفة الحالة الجنائية المميكنة» — مقدمة من مصلحة الأدلة الجنائية بوزارة الداخلية</p><p>2. سجّل الدخول بحسابك (أو اعمل حساب جديد بالرقم القومي) واملأ البيانات من واقع بطاقة الرقم القومي</p><p>3. سدّد الرسوم المقررة إلكترونيًا أولًا — الطلب ما بيتسجلش رسميًا غير بعد السداد</p><p>4. الصحيفة بتخلص خلال 72 ساعة من قبول الطلب وبتتسلّم لمندوب البريد</p><p>5. استلمها بنفسك بعد إبراز بطاقة الرقم القومي — وتابع شحنتك برقمها من خدمة «تتبع شحنتك» بتاعة البريد المصري</p><h3>⚠️ الشروط الرسمية</h3><p>• التقدم والاستلام شخصيين — الصحيفة ما بتتسلمش لحد غيرك داخل مصر</p><p>• لازم تكون بصماتك العشرية مسجلة بقطاع الأحوال المدنية قبل الطلب</p><p>• الإقامة داخل مصر شرط وقت التقدم والاستلام من هيئة البريد المصري</p><h3>💰 الرسوم</h3><p>مافيش فئات رسوم للخدمة منشورة رسميًا — بتتحدد وتتسدد إلكترونيًا عند تقديم الطلب، فاعتمد على المبلغ اللي بيظهرلك في البوابة قبل الدفع</p><h3>💡 نصيحة</h3><p>احتفظ برقم الطلب ورقم الشحنة بعد الدفع — بتتابع بيه الصحيفة على موقع البريد لحد ما تستلمها</p>""",
    "إزاي تنقل قيدك لمحافظة تانية؟":
        r"""<h3>📋 الخطوات</h3><p>1. الخدمة الرسمية اسمها «تغيير بيانات محل الإقامة بالبطاقة الشخصية طبقاً للرقم القومي» — بتقدمها سجلات قطاع مصلحة الأحوال المدنية، فروح للسجل المدني التابع لعنوانك الجديد</p><p>2. اشترِ نموذج طلب البطاقة واستوفِ بياناته واعتمده من جهة الدراسة أو العمل</p><p>3. قدّم الطلب والمستندات للموظف المختص وسدّد الرسوم</p><p>4. استلم بطاقتك الجديدة — المدة الرسمية للخدمة 15 يومًا</p><p>5. ممكن كمان من مراكز «خدمات مصر» (القاهرة — الإسكندرية — أسوان — شرم الشيخ)</p><h3>📄 المستندات</h3><p>• نموذج طلب البطاقة + أصل بطاقة الرقم القومي الحالية</p><p>• إيصال مرافق (كهرباء/مياه/غاز/تليفون) باسمك على العنوان الجديد</p><p>• لو مستأجر: عقد إيجار موثق (محضر توثيق) + إيصال مرافق باسم المؤجر</p><p>• لو ساكن مع قريب: إقرار منه بإقامتك معه إقامة دائمة + العنوان الجديد ثابت في بطاقته الرقمية + إيصال مرافق</p><p>• أرباب المعاشات: خطاب جهة صرف المعاش</p><h3>💰 الرسوم</h3><p>• الرسوم المسجلة رسميًا للخدمة: 30 جنيه (استلام خلال 15 يومًا)</p><p>• وسرعة الاستلام بتحكم فيها فئة استمارة البطاقة: عادية 50ج (15 يوم) — عاجلة 125ج (3 أيام) — خاصة 175ج (24 ساعة) — VIP إكسبريس 515ج (30 دقيقة)</p><h3>⏰ مهم</h3><p>قانون الأحوال المدنية 143/1994 (م.48) بيديك 3 شهور بس لتحديث بياناتك بعد تغيير سكنك — بعدها غرامة 50ج</p><h3>💡 نصيحة</h3><p>بعد نقل قيدك افتكر تنقل بطاقة التموين من <a href=\"https://digital.gov.eg\" target=\"_blank\">بوابة مصر الرقمية</a> عشان تفضل تصرف من محافظتك الجديدة</p>""",
    "إزاي تسجّل في منصة مصر الرقمية؟":
        r"""<h3>📋 الخطوات</h3><p>1. ادخل على <a href=\"https://digital.gov.eg\" target=\"_blank\">digital.gov.eg</a> ودوس «إنشاء حساب جديد»</p><p>2. اكتب الرقم القومي + رقم المصنع المدوّن على البطاقة + الاسم الأول لأمك واضغط «تحقق» (لو عندك أكتر من بطاقة من التجديد استخدم رقم المصنع في الأحدث)</p><p>3. اكتب رقم موبايلك المسجل باسمك — هيوصلك كود SMS من 6 أرقام</p><p>4. اكتب الكود واضغط «التالي»</p><p>5. اعمل كلمة سر قوية (حروف إنجليزية كبيرة وصغيرة + أرقام) وأكّدها بالبريد الإلكتروني</p><p>6. سجّل دخولك بعد كده بالموبايل أو الرقم القومي وكلمة السر</p><h3>⚠️ الشروط</h3><p>• موبايل مسجل باسمك شخصيًا على الرقم القومي (بيستقبل كود التفعيل)</p><p>• بياناتك متطابقة مع بطاقة الرقم القومي — خاصة الاسم الأول لأمك</p><h3>🛠️ أشهر الخدمات</h3><p>التموين — المرور — الأحوال المدنية — التوثيق — العقارات (الشهر العقاري) — القضايا والمحاكم — الضرائب العقارية — السجل التجاري — السكن الاجتماعي — التراخيص — بالتعاون مع أكتر من 9 وزارات وجهات حكومية</p><h3>✨ ملامح المنصة</h3><p>متابعة بياناتك وبيانات أسرتك وعقاراتك وسياراتك ورخصك وبطاقة التموين وكل طلباتك السابقة من مكان واحد — وخدمات بتوصل أوراقها الحكومية لعنوانك بدون حضور</p><h3>💳 السداد</h3><p>بطاقات البنوك — شركات الدفع الإلكتروني — محافظ الموبايل</p><h3>📍 القنوات الرسمية</h3><p>بوابة digital.gov.eg — بوابة misr.gov.eg — مركز الاتصال 15999 — مكاتب البريد — وتطبيق «مصر الرقمية» الرسمي على Google Play</p><h3>💡 نصيحة</h3><p>نفس الحساب يشتغل من الموبايل أو الكمبيوتر — سجّل مرة واحدة وكله بيتفتح بيه، وخدمات جديدة بتتضاف على المنصة تدريجيًا</p>""",
}

src = open(PATH, encoding="utf-8").read()
shutil.copyfile(PATH, BAK)
count_before = src.count("title:'")
problems = []
lengths = {}
for title, new_content in UPDATES.items():
    esc = re.escape(title)
    pattern = re.compile(r"(title:'" + esc + r"'.*?content:`)[^`]*(`)", re.DOTALL)
    if len(pattern.findall(src)) != 1:
        problems.append(title); continue
    src = pattern.sub(lambda m: m.group(1) + new_content + m.group(2), src, count=1)
    lengths[title] = len(new_content)

if problems:
    open(PATH, "w", encoding="utf-8").write(open(BAK, encoding="utf-8").read())
    sys.exit("فشل التطابق لمقالات: " + ", ".join(problems) + " — تم التراجع")

if src.count("title:'") != count_before or src.count("content:`") != count_before:
    sys.exit("عدد المقالات اتغير! — لم يتم الحفظ")

open(PATH, "w", encoding="utf-8").write(src)
checks = ["إصدار صحيفة الحالة الجنائية المميكنة", "مقدمة من مصلحة الأدلة الجنائية بوزارة الداخلية",
          "72 ساعة من قبول الطلب", "بقطاع الأحوال المدنية", "تتبع شحنتك",
          "مافيش فئات رسوم للخدمة منشورة رسميًا",
          "تغيير بيانات محل الإقامة بالبطاقة الشخصية", "بتقدمها سجلات قطاع مصلحة الأحوال المدنية",
          "واعتمده من جهة الدراسة أو العمل", "الرسوم المسجلة رسميًا للخدمة: 30 جنيه",
          "المدة الرسمية للخدمة 15 يومًا", "مراكز «خدمات مصر» (القاهرة — الإسكندرية — أسوان — شرم الشيخ)",
          "وأكّدها بالبريد الإلكتروني", "مركز الاتصال 15999", "بوابة misr.gov.eg",
          "السكن الاجتماعي", "محافظ الموبايل", "بتتضاف على المنصة تدريجيًا"]
gone = ["ecriminal.gov.eg", "— التأمينات —", "~75ج", "مستعجل 100-150ج",
        "توصيل بريد 40-60ج", "البريد الإلكتروني اختياري", "صلاحيته 3 شهور",
        "بس التوقيع غالبًا حضوري"]
print("OK — تم تحديث 3 مقالات، عدد المقالات الكلي:", count_before)
for t, L in lengths.items():
    print(f"  طول محتوى {t!r}: {L} حرف")
for c in checks:
    print(("✓ " if c in src else "✗ مفقود ") + c)
for c in gone:
    print(("✓ اتحذف: " if c not in src else "✗ لسه موجود: ") + c)
